def activate_approved(apps, schema_editor):
    Option = apps.get_model("profiles", "VocabularyOption")
    for vocabulary, options in APPROVED.items():
        for order, (code, label) in enumerate(options):
            Option.objects.update_or_create(
                vocabulary=vocabulary,
                code=code,
                defaults={"label_en": label, "sort_order": order * 10, "is_active": True},
            )


def deactivate_approved(apps, schema_editor):
    # Reverse: deactivate (rows are never deleted; the guard forbids it).
    Option = apps.get_model("profiles", "VocabularyOption")
    for vocabulary, options in APPROVED.items():
        Option.objects.filter(vocabulary=vocabulary, code__in=[c for c, _ in options]).update(
            is_active=False
        )


